-- Acerta as sequências de id DEPOIS da carga.
--
-- As tabelas nascem com `id bigint generated by default as identity`, e a
-- sequência começa em 1. A carga grava os ids da planilha explicitamente — até
-- 1509 em unidades — sem tocar na sequência. Se ninguém acertar isso, o
-- primeiro cadastro feito pelo app pede o próximo valor, recebe 1, e falha com
-- "duplicate key value violates unique constraint".
--
-- É a mesma correção que o 0011 fazia, separada em arquivo próprio porque agora
-- a ordem importa: identity já vem do 0001, e o setval só faz sentido com os
-- dados dentro. Rodar isto ANTES da carga não adianta nada.
--
-- Pode ser rodado quantas vezes for preciso.

do $$
declare
  t record;
  seq text;
  maior bigint;
begin
  for t in
    select c.table_name
      from information_schema.columns c
      join information_schema.tables tb
        on tb.table_schema = c.table_schema and tb.table_name = c.table_name
     where c.table_schema = 'public'
       and c.column_name  = 'id'
       and c.is_identity  = 'YES'
       and tb.table_type  = 'BASE TABLE'
     order by c.table_name
  loop
    seq := pg_get_serial_sequence('public.' || quote_ident(t.table_name), 'id');
    continue when seq is null;

    execute format('select coalesce(max(id), 0) from public.%I', t.table_name) into maior;

    -- `false` no terceiro argumento: o próximo nextval devolve exatamente este
    -- número. Com `true` ele devolveria maior+2, deixando um buraco.
    perform setval(seq, maior + 1, false);
    raise notice 'sequência de % começa em %', t.table_name, maior + 1;
  end loop;
end $$;
